'{
  "$schema": "https://vega.github.io/schema/vega-lite/v5.json",
  "data": {
    "name": "dataset"
  },
  "width": 298,
  "height": 124,
  "transform": [
    {
      "window": [
        {
          "op": "row_number",
          "as": "k"
        }
      ],
      "sort": [
        {
          "field": "Week Starting"
        }
      ]
    },
    {
      "joinaggregate": [
        {
          "op": "max",
          "field": "k",
          "as": "last"
        }
      ]
    }
  ],
  "autosize": {
    "type": "pad"
  },
  "layer": [
    {
      "mark": {
        "type": "area",
        "color": {
          "x1": 1,
          "y1": 1,
          "x2": 1,
          "y2": 0,
          "gradient": "linear",
          "stops": [
            {
              "offset": 0,
              "color": "rgba(27,175,122,0.03)"
            },
            {
              "offset": 1,
              "color": "rgba(27,175,122,0.38)"
            }
          ]
        }
      },
      "encoding": {
        "x": {
          "field": "k",
          "type": "quantitative",
          "title": null,
          "scale": {
            "domain": [
              0.7,
              8.3
            ],
            "nice": false,
            "zero": false
          },
          "axis": {
            "values": [
              1,
              2,
              3,
              4,
              5,
              6,
              7,
              8
            ],
            "labelExpr": "''Wk '' + datum.value",
            "grid": false
          }
        },
        "y": {
          "field": "Cumulative Hours Saved",
          "type": "quantitative",
          "title": null,
          "scale": {
            "domain": [
              0,
              28
            ]
          },
          "axis": {
            "values": [
              0,
              10,
              20
            ],
            "labelExpr": "datum.value + '' h''"
          }
        }
      }
    },
    {
      "mark": {
        "type": "line",
        "color": "#1BAF7A",
        "strokeWidth": 2.4
      },
      "encoding": {
        "x": {
          "field": "k",
          "type": "quantitative",
          "title": null,
          "scale": {
            "domain": [
              0.7,
              8.3
            ],
            "nice": false,
            "zero": false
          },
          "axis": {
            "values": [
              1,
              2,
              3,
              4,
              5,
              6,
              7,
              8
            ],
            "labelExpr": "''Wk '' + datum.value",
            "grid": false
          }
        },
        "y": {
          "field": "Cumulative Hours Saved",
          "type": "quantitative",
          "title": null,
          "scale": {
            "domain": [
              0,
              28
            ]
          },
          "axis": {
            "values": [
              0,
              10,
              20
            ],
            "labelExpr": "datum.value + '' h''"
          }
        }
      }
    },
    {
      "mark": {
        "type": "point",
        "filled": true,
        "size": 34,
        "color": "#1BAF7A",
        "stroke": "white",
        "strokeWidth": 1,
        "opacity": 1
      },
      "encoding": {
        "x": {
          "field": "k",
          "type": "quantitative",
          "title": null,
          "scale": {
            "domain": [
              0.7,
              8.3
            ],
            "nice": false,
            "zero": false
          },
          "axis": {
            "values": [
              1,
              2,
              3,
              4,
              5,
              6,
              7,
              8
            ],
            "labelExpr": "''Wk '' + datum.value",
            "grid": false
          }
        },
        "y": {
          "field": "Cumulative Hours Saved",
          "type": "quantitative",
          "title": null,
          "scale": {
            "domain": [
              0,
              28
            ]
          },
          "axis": {
            "values": [
              0,
              10,
              20
            ],
            "labelExpr": "datum.value + '' h''"
          }
        },
        "tooltip": [
          {
            "field": "Week Starting",
            "type": "temporal",
            "format": "%-d %b %Y",
            "title": "Week starting"
          },
          {
            "field": "Cumulative Hours Saved",
            "format": ".1f",
            "title": "Hours saved"
          }
        ]
      }
    },
    {
      "transform": [
        {
          "filter": "datum.k == datum.last"
        },
        {
          "calculate": "format(datum[''Cumulative Hours Saved''], ''.1f'') + '' h''",
          "as": "lab"
        }
      ],
      "mark": {
        "type": "text",
        "align": "right",
        "dx": 0,
        "dy": -14,
        "fontSize": 11.5,
        "fontWeight": 600,
        "color": "#101828"
      },
      "encoding": {
        "x": {
          "field": "k",
          "type": "quantitative",
          "title": null,
          "scale": {
            "domain": [
              0.7,
              8.3
            ],
            "nice": false,
            "zero": false
          },
          "axis": {
            "values": [
              1,
              2,
              3,
              4,
              5,
              6,
              7,
              8
            ],
            "labelExpr": "''Wk '' + datum.value",
            "grid": false
          }
        },
        "y": {
          "field": "Cumulative Hours Saved",
          "type": "quantitative",
          "title": null,
          "scale": {
            "domain": [
              0,
              28
            ]
          },
          "axis": {
            "values": [
              0,
              10,
              20
            ],
            "labelExpr": "datum.value + '' h''"
          }
        },
        "text": {
          "field": "lab"
        }
      }
    }
  ]
}'

'{
  "background": null,
  "font": "Segoe UI",
  "view": {
    "stroke": null
  },
  "padding": 2,
  "axis": {
    "labelFont": "Segoe UI",
    "labelFontSize": 10,
    "labelColor": "#667085",
    "titleFont": "Segoe UI",
    "titleFontSize": 10,
    "titleColor": "#667085",
    "titleFontWeight": "normal",
    "domain": false,
    "ticks": false,
    "gridColor": "#EEF0F4",
    "labelPadding": 6
  },
  "legend": {
    "labelFont": "Segoe UI",
    "labelFontSize": 10.5,
    "labelColor": "#344054",
    "symbolType": "circle",
    "symbolSize": 70,
    "title": null,
    "orient": "top",
    "direction": "horizontal",
    "columnPadding": 14
  },
  "text": {
    "font": "Segoe UI",
    "fontSize": 11,
    "color": "#344054"
  },
  "title": {
    "font": "Segoe UI"
  },
  "concat": {
    "spacing": 8
  }
}'
